  "evan-slater": {
    "id": "evan-slater",
    "type": "person",
    "name": "Evan Slater",
    "sport": [
      "surf"
    ],
    "born": "c. 1972",
    "hometown": "Ventura, California",
    "bio": "Evan Slater is a surf journalist, big-wave surfer, and surf industry executive from Ventura, California. He studied at UC San Diego (BA Sociology / Creative Writing, 1994). As a young surfer he competed on the NSSA circuit alongside future pros Taylor Knox, Pat O'Connell, and Rob Machado before shifting focus to big-wave riding, discovering Todos Santos during his college freshman year. He began his editorial career at Surfer magazine (1996-2000, finishing as editor) before joining Swell.com/Surfline during the dot-com boom. He then served as editor-in-chief of Surfing magazine for 8 years (2001-2009) before moving to VP Marketing at Hurley for 10 years and VP Global Marketing at Billabong for 5 years. He became Chief Marketing Officer at Sun Bum in 2023. He authored the biographical entries for Surfline's Surfing A-to-Z encyclopedia. He has surfed Mavericks extensively, catching some of his biggest waves there in 1994 during a historic swell the same week Mark Foo died.",
    "connections": [
      {
        "id": "rob-machado",
        "label": "NSSA contemporaries"
      }
    ],
    "source": "surfline.com; juicemagazine.com; instagram.com/nssasurf"
  },
