  "jaws-peahi-maui": {
    "id": "jaws-peahi-maui",
    "type": "location",
    "name": "Jaws (Pe'ahi)",
    "sport": [
      "surf"
    ],
    "status": "active",
    "era": "1990s-present",
    "bio": "Pe'ahi, known universally as Jaws, is a massive big-wave break on the north shore of Maui, Hawaii. Driven by deep-ocean swells that suddenly hit a shallow reef, Jaws produces waves regularly exceeding 50 feet and occasionally 70 feet or more in face height. Laird Hamilton and the tow-in crew pioneered big-wave surfing here in the 1990s and it has since transitioned to paddle surfing as big-wave boards and safety equipment have improved. The WSL has held Big Wave Tour events at Jaws, and Laura Enever set her world record here in 2023.",
    "hometown": "Haiku, Maui, Hawaii"
  },
