  "nick-carroll": {
    "id": "nick-carroll",
    "type": "person",
    "name": "Nick Carroll",
    "sport": [
      "surf"
    ],
    "born": "1959",
    "hometown": "Newport, New South Wales, Australia",
    "bio": "Nick Carroll (born 1959 in Brisbane) is arguably the world's most respected surf journalist and author, and the older brother of two-time world champion Tom Carroll. The family moved to Newport, NSW in 1961 where Nick grew up surfing and became a serious competitive surfer — winning the Australian National Surfing Championships twice (1979 and 1981). He was a founding member of the Newport Plus Surf Club. Transitioning from surfing to journalism, he began with Tracks magazine (editor 1984-86), then served as editor-in-chief of Surfing magazine in the United States for Western Empire Publications. He later edited Deep magazine (1997-2000) and then joined Surfline following their acquisition of Coastalwatch in 2019, initially as Australia Editor, eventually overseeing all Surfline editorial teams worldwide. He is the author of TC, the biography of his brother Tom Carroll, which won the Surf Culture Award at the 2014 Australian Surfing Awards. He also co-wrote the ABC documentaries Bombora and Wide Open Road and authored Out the Back with Bondi Rescue. In 2025 he launched the surf culture podcast 'We Shouldn't Be Friends' with Hannah Anderson. He holds a life membership at Newport Surf Club (2020) and won Australian Ironman Masters Championships in 2021 and 2022.",
    "siblings": [
      "Tom Carroll"
    ],
    "achievements": [
      "2x Australian National Surfing Champion (1979, 1981)",
      "Former Editor-in-Chief, Surfing Magazine",
      "Surfline Australia Editor / Global Editorial Director",
      "2021 & 2022 Australian Ironman Masters Champion"
    ],
    "source": "surfline.com; en.wikipedia.org/wiki/Nick_Carroll; penguin.com.au"
  },
  "nick-gabaldon": {
    "id": "nick-gabaldon",
    "type": "athlete",
    "name": "Nick Gabaldon",
    "sport": [
      "surf"
    ],
    "location": "Santa Monica / Malibu, CA",
    "era": "1940s–1951",
    "bio": "Nick Gabaldon (1927–1951) is recognized as the first documented Black surfer in modern American surf history. A Santa Monica native, he taught himself to surf at the segregated Bay Street Beach and then rode the nine miles to Malibu — the premier California surf spot of the era — which was technically off-limits to Black beachgoers under Jim Crow-era segregation. He died in a surfing accident at Malibu in 1951 at age 24. His story, long forgotten, was rediscovered in the 2000s and he is now celebrated as a pioneer of diversity in surfing. A plaque at Malibu commemorates him.",
    "connections": [
      {
        "id": "malibu",
        "label": "Surfed Malibu breaking color barrier"
      }
    ],
    "source": "encyclopediaofsurfing.com; surfline.com; en.wikipedia.org/wiki/Nick_Gabaldon"
  },
